-- Sigorta datasi: MySQL 8.0 ucun tam skript (cedveller + data)
-- Istifade: MySQL Workbench -> File -> Open SQL Script -> bu fayli secin -> ildirim (Execute) duymesi
-- Skript tekrar isledile biler (cedvelleri silib yeniden yaradir).

CREATE DATABASE IF NOT EXISTS sigorta CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE sigorta;
SET NAMES utf8mb4;

DROP TABLE IF EXISTS iddialar;
DROP TABLE IF EXISTS odenisler;
DROP TABLE IF EXISTS polisler;
DROP TABLE IF EXISTS agentler;
DROP TABLE IF EXISTS musteriler;

CREATE TABLE musteriler (
    musteri_id        INT PRIMARY KEY,
    ad                VARCHAR(50),
    soyad             VARCHAR(50),
    cins              VARCHAR(10),
    dogum_tarixi      DATE,
    seher             VARCHAR(50),
    qeydiyyat_tarixi  DATE
);

CREATE TABLE agentler (
    agent_id            INT PRIMARY KEY,
    agent_adi           VARCHAR(100),
    filial              VARCHAR(50),
    ise_baslama_tarixi  DATE
);

CREATE TABLE polisler (
    polis_id         INT PRIMARY KEY,
    musteri_id       INT NOT NULL,
    agent_id         INT NOT NULL,
    sigorta_novu     VARCHAR(50),
    baslama_tarixi   DATE,
    bitme_tarixi     DATE,
    sigorta_meblegi  DECIMAL(12,2),
    illik_premium    DECIMAL(12,2),
    odenis_tezliyi   VARCHAR(20),
    status           VARCHAR(20),
    FOREIGN KEY (musteri_id) REFERENCES musteriler(musteri_id),
    FOREIGN KEY (agent_id)   REFERENCES agentler(agent_id)
);

CREATE TABLE odenisler (
    odenis_id      INT PRIMARY KEY,
    polis_id       INT NOT NULL,
    odenis_tarixi  DATE,
    mebleg         DECIMAL(12,2),
    odenis_usulu   VARCHAR(20),
    gecikme_gun    INT,
    FOREIGN KEY (polis_id) REFERENCES polisler(polis_id)
);

CREATE TABLE iddialar (
    iddia_id             INT PRIMARY KEY,
    polis_id             INT NOT NULL,
    iddia_tarixi         DATE,
    hadise_novu          VARCHAR(50),
    teleb_olunan_mebleg  DECIMAL(12,2),
    odenilen_mebleg      DECIMAL(12,2) NULL,
    status               VARCHAR(20),
    baxilma_tarixi       DATE NULL,
    FOREIGN KEY (polis_id) REFERENCES polisler(polis_id)
);

