-- Yoxlama (gozlenilen: 300, 10, 620, 2911, 316)
SELECT 'musteriler' AS cedvel, COUNT(*) AS setir FROM musteriler
UNION ALL SELECT 'agentler',  COUNT(*) FROM agentler
UNION ALL SELECT 'polisler',  COUNT(*) FROM polisler
UNION ALL SELECT 'odenisler', COUNT(*) FROM odenisler
UNION ALL SELECT 'iddialar',  COUNT(*) FROM iddialar;
